G=$(powershell -c "[guid]::NewGuid().ToString()" | tr -d '\r') && cat > AsyncData.cs <<EOF
using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;

namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Data")]
    public interface IMyDataPack : IBettaCollection
    {
        [GrasshopperMethod("Async Stats", "Mean and standard deviation of a list of numbers, computed asynchronously", Guid = "$G")]
        Task<(double Mean, double StdDev)> AsyncStats(
            [GrasshopperParameter("Values")] List<double> values,
            CancellationToken cancellationToken);
    }

    public class MyDataPack : IMyDataPack
    {
        public Task<(double Mean, double StdDev)> AsyncStats(List<double> values, CancellationToken cancellationToken)
        {
            return Task.Run(() =>
            {
                if (values == null || values.Count == 0) return (0.0, 0.0);

                double sum = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    sum += v;
                }
                double mean = sum / values.Count;

                double squares = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    squares += (v - mean) * (v - mean);
                }
                return (mean, Math.Sqrt(squares / values.Count));
            }, cancellationToken);
        }
    }
}
EOF
dotnet build 2>&1 | tail -5
